MOD = 1000000007

def calculate_initial_edges(n):
    return (2 ** n - 1) * 2

def mirror_right(edges, n):
    return (edges + (2 ** (n - 1) - 1)) % MOD

def mirror_left(edges, n):
    return (edges + (2 ** (n - 1) - 1)) % MOD

def mirror_top(edges, n):
    return (edges + (2 ** (n - 1) - 1)) % MOD

def mirror_bottom(edges, n):
